const APP={user:null,screen:1,loading:false,drawer:false,filter:'',tab:'All',items:[],questions:[],answers:{},course:'Private Pilot Licence (PPL)',selected:null,timer:null,timerEnd:0,lastBooking:null,lastTicket:null,search:'',draft:{},view:'',settings:{}};
const $=sel=>document.querySelector(sel), $$=sel=>Array.from(document.querySelectorAll(sel));
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=s=>{if(!s)return '—';if(/^\d\d\d\d-\d\d-\d\d/.test(String(s))){let d=new Date(String(s));return isNaN(d)?E(s):d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});}return E(s)};
const short=s=>String(s??'').slice(0,100);
function toast(message,error=false){let t=$('#toast');t.textContent=message;t.style.background=error?'#a83243':'#0a2c52';t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4600)}
async function api(path,method='GET',body){let r=await fetch('/api'+path,{method,headers:{...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,credentials:'same-origin'});let data=await r.json().catch(()=>({error:'Server response could not be read'}));if(!r.ok)throw Error(data.error||'Request failed');return data}
async function refreshMe(){let d=await api('/me');APP.user=d.user;APP.settings=d;return d}
const S=id=>SCREENS.find(s=>s.id===id)||SCREENS[0];
const role=()=>APP.user?.role||'guest';
const management=()=>['admin','ceo','finance','admissions','instructor'].includes(role());
const admin=()=>['admin','ceo'].includes(role());
const canEdit=kind=>admin()||(role()==='instructor'&&['lessons','assignments','questions','exams','classes','flights','attendance','competencies','resources','submissions','grades','messages'].includes(kind))||(role()==='finance'&&['payments','invoices','refunds','expenses','reports'].includes(kind))||(role()==='admissions'&&['tickets','bookings','applications','seminars','intakes'].includes(kind))||(role()==='student'&&['flights','support','payments','notes','messages','submissions','documents','attendance','reviews','applications'].includes(kind));
const canApprove=kind=>['admin','ceo'].includes(role())||(['payments','refunds','invoices'].includes(kind)&&role()==='finance')||(['tickets','bookings','applications'].includes(kind)&&role()==='admissions')||(['flights','competencies','submissions','grades'].includes(kind)&&role()==='instructor');
function btn(text,action,cls='primary',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`}
function tag(v){let str=String(v||'Pending');let cl=/paid|approved|completed|published|open|verified|available|present|competent|signed|active|pass|confirmed/i.test(str)?'green':/fail|rejected|cancelled|overdue|maintenance/i.test(str)?'red':/pending|review|draft|upcoming|scheduled/i.test(str)?'amber':'blue';return `<span class="badge ${cl}">${E(str)}</span>`}
function hero(title,desc,cls='ppl',buttons=''){return `<section class="hero ${cls}"><div class="hero-content"><div class="eyebrow">IRVINAERO AVIATION · TRAIN · LEARN · FLY</div><h2>${title}</h2><p>${desc}</p><div class="flex" style="flex-wrap:wrap">${buttons}</div></div></section>`}
const metricCard=(icon,key,label)=>`<div class="card stat"><div class="symbol">${icon}</div><div><div class="stat-val" data-metric="${key}">…</div><div class="stat-label">${E(label)}</div></div></div>`;
const stat=(icon,value,label,foot='')=>`<div class="card stat"><div class="symbol">${icon}</div><div><div class="stat-val">${E(value)}</div><div class="stat-label">${E(label)}</div>${foot?`<div class="stat-foot">${E(foot)}</div>`:''}</div></div>`;
function head(s,button=''){return `<header class="page-head"><div><div class="kicker">IRVINAERO ACADEMY · SCREEN ${String(s.id).padStart(2,'0')} / 64</div><h1 class="page-title">${E(s.title)}</h1><p class="sub">${E(s.description)}</p></div><div class="buttons">${button}</div></header>`}
function recData(item,key,fallback='—'){return E(item.data?.[key]??fallback)}
function cardList(list,kind=APP.items[0]?.kind||'courses'){if(!list.length)return empty(`No ${kind} records yet.`,canEdit(kind)?`Use “New ${kind.slice(0,-1)}” to create the first entry.`:'Records will appear here when published.');return `<div class="stack">${list.map((r,i)=>`<article class="course-card" data-record="${E(r.id)}"><div class="course-pic">${({'courses':'✈','lessons':'📖','aircraft':'🛩','seminars':'🎤','flights':'🛩','tickets':'🎟','payments':'💳','applications':'🎓','invoices':'🧾','certificates':'🏅','maintenance':'🛠','support':'🎧','questions':'❓','assignments':'📋'}[kind]||'📘')}</div><div style="flex:1;min-width:0"><strong>${E(r.title)}</strong><p>${E(short(r.data?.description||r.data?.message||r.data?.course||r.data?.location||r.data?.venue||r.data?.notes||r.data?.date||r.data?.status||'View details and manage this record.'))}</p><div class="flex" style="flex-wrap:wrap">${tag(r.data?.status||r.data?.category||kind)}<span class="tiny muted">${E(r.id.toUpperCase())}</span></div></div><button class="btn sm light" data-action="details" data-id="${E(r.id)}">View →</button></article>`).join('')}</div>`}
function empty(title,desc=''){return `<div class="empty"><div class="symbol">✈</div><strong>${E(title)}</strong><p>${E(desc)}</p></div>`}
function tableRows(list,kind){if(!list.length)return empty('No records found','Try another filter or add a new record.');return `<div class="table-wrap"><table class="table"><thead><tr><th>Record / name</th><th>Details</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(r=>`<tr><td><strong>${E(r.title)}</strong><div class="tiny muted">${E(r.id.toUpperCase())}</div></td><td>${E(short(r.data?.course||r.data?.student||r.data?.date||r.data?.venue||r.data?.amount||r.data?.category||r.data?.description||'—'))}</td><td>${tag(r.data?.status||'Recorded')}</td><td><button class="rowbtn" data-action="details" data-id="${E(r.id)}">Open →</button></td></tr>`).join('')}</tbody></table></div>`}
function subSection(title,inner,extra=''){return `<section class="card"><div class="flex space" style="margin-bottom:13px"><h3 class="card-title" style="margin:0">${title}</h3>${extra}</div>${inner}</section>`}
function formFields(kind,values={}){let defs=FIELDS[kind]||[['description','Description','textarea']];return `<div class="form-grid">${defs.map(([key,label,type='text',opts,required])=>{let val=values[key]??'';return `<div class="field" ${type==='textarea'?'style="grid-column:1/-1"':''}><label for="field-${E(key)}">${E(label)} ${required?'<span style="color:#df4c58">*</span>':''}</label>${type==='textarea'?`<textarea class="textarea" id="field-${E(key)}" name="${E(key)}" ${required?'required':''}>${E(val)}</textarea>`:type==='select'?`<select class="select" id="field-${E(key)}" name="${E(key)}" ${required?'required':''}><option value="">Select…</option>${opts.map(o=>`<option value="${E(o)}" ${String(val)===o?'selected':''}>${E(o)}</option>`).join('')}</select>`:`<input class="input" id="field-${E(key)}" name="${E(key)}" type="${type}" value="${E(val)}" ${required?'required':''} ${type==='number'?'min="0" step="any"':''}>`}</div>`}).join('')}</div>`}
function closeModal(){let m=$('#modal');if(m.open)m.close()}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h3>${E(title)}</h3><button class="close" type="button" data-action="close">✕</button></div><div class="modal-body">${body}</div>`;$('#modal').showModal()}
function openEditor(kind,id){let r=APP.items.find(x=>x.id===id);if(kind==='users')return toast('Use staff administration for role details.',true);let body=`<form id="edit-form" data-kind="${E(kind)}" data-id="${E(id||'')}"><div class="field"><label for="rec-title">Record title</label><input id="rec-title" name="title" class="input" value="${E(r?.title||'')}" required maxlength="250"></div>${formFields(kind,r?.data||{})}<div class="flex" style="justify-content:flex-end;margin-top:12px">${btn('Cancel','close','white')}<button class="btn primary" type="submit">${id?'Save changes':'Create record'} →</button></div></form>`;modal(`${id?'Edit':'New'} ${kind.slice(0,-1)}`,body)}
function editorButton(kind,label){return canEdit(kind)?btn(label||`＋ New ${kind.slice(0,-1)}`,'new','primary',`data-kind="${kind}"`):''}
function dashboardNumbers(){let data=APP.items;return `${stat('👥',data.length,'Records in current view')}${stat('📘',SCREENS.length,'Designed screens')}${stat('🛡','6','Academy account roles')}${stat('✅','Online','Local database connected','Saved to SQLite')}`}
function graph(){let vals=[28,36,47,54,70,85],max=100;let lines=vals.map((v,i)=>`${30+i*86},${188-v*1.55}`).join(' ');return `<svg class="chart-svg" viewBox="0 0 520 220" role="img" aria-label="Illustrative monthly performance chart">${[0,1,2,3].map(i=>`<line class="chart-grid" x1="32" x2="511" y1="${42+i*46}" y2="${42+i*46}"/>`).join('')}<polygon class="chart-area" points="30,195 ${lines} 460,195"/><polyline class="chart-path" points="${lines}"/>${['Jul','Aug','Sep','Oct','Nov','Dec'].map((x,i)=>`<text class="chart-label" x="${26+i*86}" y="215">${x}</text>`).join('')}</svg><div class="hint">Chart values are illustrative until real enrolment analytics are configured.</div>`}
function navTile(id,icon,title,sub){return `<button class="tile" data-go="${id}"><span class="emoji">${icon}</span><strong>${E(title)}</strong><small>${E(sub||S(id).description)}</small></button>`}
function go(id){stopCamera();let n=Number(id);if(!S(n)||!Number.isInteger(n))n=1;APP.screen=n;APP.tab='All';APP.filter='';APP.view='';APP.answers={};closeModal();location.hash='#/screen/'+n;APP.drawer=false;render();window.scrollTo(0,0)}
function href(id){return `#/screen/${id}`}
function shell(content){let s=S(APP.screen);let g=GROUPS.map(g=>{let arr=SCREENS.filter(x=>x.group===g);return `<div class="nav-group"><div class="nav-group-label">${E(g)} · ${arr.length}</div>${arr.map(x=>`<a class="nav-link ${APP.screen===x.id?'active':''}" href="${href(x.id)}" data-go="${x.id}"><span class="nav-num">${x.id}</span><span style="overflow:hidden;text-overflow:ellipsis">${E(x.title)}</span></a>`).join('')}</div>`}).join('');let name=APP.user?.name||'Guest';let initials=name.split(' ').map(x=>x[0]).slice(0,2).join('');$('#app').innerHTML=`<div class="app-shell"><aside class="side ${APP.drawer?'open':''}"><div class="brand"><div class="brand-plane">✈</div><div><div class="brand-name">IRVINAERO</div><div class="brand-sub">AVIATION</div><small>E-LEARNING & TRAINING</small></div></div><div class="nav-scroll">${g}</div><div class="nav-bottom"><div class="flex"><div class="avatar" style="width:33px;height:33px">${E(initials)}</div><div><strong style="font-size:12px">${E(name)}</strong><span class="mini">${role().toUpperCase()} · Local preview</span></div></div></div></aside><div class="scrim ${APP.drawer?'open':''}" data-action="drawer"></div><div class="main"><header class="topbar"><div class="lefttop"><button class="menu-trigger" data-action="drawer" aria-label="Open navigation">☰</button><div><div class="top-title">${E(s.title)}</div><div class="breadcrumbs">IrvinAero Aviation / ${E(s.group)} / Screen ${s.id}</div></div></div><div class="top-actions"><input class="searchtop" type="search" placeholder="Find a screen…" id="screen-search" aria-label="Find a screen"><button class="btn icon white hide-mobile" data-go="27" title="Notifications">🔔</button>${APP.user?`<span class="roletag">${E(role())}</span><button class="btn sm white" data-action="logout">Log out</button>`:`<button class="btn sm primary" data-go="10">Log in</button>`}<div class="avatar" title="${E(name)}">${E(initials)}</div></div></header><main class="body" id="screen-content">${content}<div class="footer">IRVINAERO AVIATION · Training platform staging build · Screen ${s.id} of 64 · No live payments or licensing verification</div></main></div></div>`;}
async function getRecords(kind){let data=await api('/records?kind='+encodeURIComponent(kind));return data.items||[]}
async function render(){let s=S(APP.screen);if(APP.loading)return;APP.loading=true;try{let needAuth=!['home','catalog','programmes','course','courseApplyDetail','seminar','seminarBooking','seminarForm','ticket','flightExperience','flightPackage','applicationForm','track','login','bookingForm','flightConfirmation','intakes'].includes(s.mode);APP.items=await getRecords(s.kind).catch(()=>[]);let html='';switch(s.mode){
case'home':html=homePage(s);break;
case'catalog':html=catalog(s);break;case'programmes':html=programmesPage(s);break;
case'course':html=courseDetail(s);break;case'courseApplyDetail':html=courseApplyDetail(s);break;
case'seminar':html=seminarPage(s);break;case'seminarBooking':html=seminarBookingPage(s);break;
case'seminarForm':html=seminarRegistration(s);break;
case'ticket':html=ticketPage(s);break;
case'flightExperience':html=flightPage(s);break;case'flightPackage':html=flightPackagePage(s);break;
case'applicationForm':html=applicationPage(s);break;
case'track':html=trackingPage(s);break;
case'login':html=loginPage(s);break;
case'myCourses':html=myCourses(s);break;
case'lessons':html=lessonPage(s);break;
case'assignments':html=assignmentPage(s);break;
case'quiz':html=quizPage(s,false);break;
case'exam':html=quizPage(s,true);break;
case'results':html=resultsPage(s);break;
case'calendar':html=calendarPage(s);break;
case'live':html=livePage(s);break;
case'attendance':html=attendancePage(s);break;
case'logbook':html=logbookPage(s);break;case'flightReview':html=flightReviewPage(s);break;
case'payment':html=paymentPage(s);break;
case'documents':html=listPage(s,'Downloadable academy records');break;
case'profile':html=profilePage(s);break;
case'messages':html=messagesPage(s);break;
case'support':html=supportPage(s);break;
case'list':html=listPage(s);break;
case'uploads':html=uploadPage(s);break;
case'progress':html=progressPage(s);break;
case'account':html=accountPage(s);break;
case'admissions':html=admissionsPage(s);break;
case'intakes':html=intakesPage(s);break;
case'bookingForm':html=bookingForm(s);break;
case'flightConfirmation':html=flightConfirmation(s);break;
case'aircraftSchedule':html=aircraftSchedule(s);break;
case'instructor':html=instructorPage(s);break;
case'studentDirectory':html=studentDirectory(s);break;
case'builder':html=builderPage(s);break;
case'reports':html=reportsPage(s);break;case'analyticsDashboard':html=analyticsDashboardPage(s);break;
case'admin':html=adminPage(s);break;
case'staff':html=staffPage(s);break;
case'content':html=contentPage(s);break;
case'examManager':html=examManager(s);break;
case'finance':html=financePage(s);break;
case'certManager':html=certManager(s);break;
case'seminarManager':html=seminarManager(s);break;
case'checkin':html=checkinPage(s);break;
case'fleet':html=fleetPage(s);break;
case'maintenance':html=maintenancePage(s);break;
case'settings':html=settingsPage(s);break;
case'executive':html=executivePage(s);break;
case'communications':html=communicationsPage(s);break;
case'security':html=securityPage(s);break;
default:html=listPage(s)}
if(needAuth&&!APP.user){html=loginGate(s)}else if(APP.user&&!roleAllowed(s)){html=roleGate(s)}shell(html);attachInputs();}catch(e){shell(head(s)+`<div class="warning">${E(e.message)}. ${btn('Try again','reload','light')}</div>`);console.error(e);}finally{APP.loading=false}}
const listFilter=items=>APP.filter?items.filter(r=>(r.title+' '+JSON.stringify(r.data)).toLowerCase().includes(APP.filter.toLowerCase())):items;
function listPage(s,subtitle){return `${head(s,editorButton(s.kind))}<div class="grid cols-main"><section class="card">${subtitle?`<div class="hint" style="margin-bottom:14px">${E(subtitle)}</div>`:''}<div class="flex" style="margin-bottom:14px"><input class="input" id="record-filter" value="${E(APP.filter)}" placeholder="Search ${E(s.kind)}…"></div><div id="list-panel">${tableRows(listFilter(APP.items),s.kind)}</div></section>${subSection('Actions & navigation',`<div class="help-list">${quickLinks(s)}</div>`)}</div>`}
function quickLinks(s){let ids={Public:[2,4,7,10],Admissions:[8,9,39,50],Accounts:[10,24,30],Student:[11,12,13,16,20,21],Instructor:[46,47,48,20],Finance:[21,22,54,62],Operations:[45,58,59],Administration:[50,51,52,53,54,55,56,57,60,64],Management:[49,61,62]};return (ids[s.group]||[1,2,10]).filter(id=>id!==s.id).slice(0,6).map(id=>`<button data-go="${id}">${S(id).icon} ${E(S(id).title)} <span>→</span></button>`).join('')}

function roleAllowed(s){let r=role();if(['admin','ceo'].includes(r))return true;if(s.group==='Management'||s.group==='Administration')return false;if(s.group==='Instructor')return r==='instructor';if(s.group==='Finance')return r==='finance';if(s.group==='Operations')return r==='instructor';if(s.id===31)return r==='admissions';return true}
function roleGate(s){return `${head(s)}<div class="grid cols-main">${subSection('Access restricted',`<div class="warning">This screen is reserved for authorised academy personnel. Your active role is <strong>${E(role())}</strong>. Switch to an appropriate authorised account to access these functions.</div><div style="margin-top:17px">${btn('Open My Dashboard','goto','primary','data-to="11"')}${btn('Account Settings','goto','light','data-to="30"')}</div>`)}${subSection('Available screens',`<div class="help-list">${[1,2,10,11,16,24].map(i=>`<button data-go="${i}">${E(S(i).title)} <span>→</span></button>`).join('')}</div>`)}</div>`}
function programmesPage(s){return `${head(s,btn('Apply for a Programme','goto','primary','data-to="8"'))}${hero('Aviation Training Programmes','Explore pathways from first flight through advanced ratings and cabin crew preparation.','airport','')}<div class="grid cols3" style="margin-top:18px">${APP.items.map((c,i)=>`<div class="card"><div class="flex space"><div class="course-pic">${c.data.category==='Cabin Crew'?'👩‍✈️':'🛩'}</div>${tag(c.data.category||'Training')}</div><h3>${E(c.title)}</h3><p class="sub" style="min-height:64px">${E(c.data.description||'Programme information available from admissions.')}</p><p class="tiny muted">Duration: ${E(c.data.duration||'Confirm with admissions')}</p>${btn('Programme Requirements →','chooseCourse','primary full',`data-course="${E(c.title)}"`)}</div>`).join('')}</div>`}
function courseApplyDetail(s){let c=APP.items.find(x=>x.title===APP.course)||APP.items[0];return `${head(s,btn('Start Application','goto','primary','data-to="8"'))}${c?hero(E(c.title),'Training overview, academic requirements, timetable and study information.','ppl',''):''}<div class="grid cols-main" style="margin-top:18px">${subSection('Course eligibility and requirements',`<div class="stack"><p>Programme: <strong>${E(c?.title||APP.course)}</strong></p><p>Duration: <strong>${E(c?.data.duration||'Confirm with admissions')}</strong></p><p>Fees: <strong>${E(c?.data.fee||'Contact admissions')}</strong></p><p>Approval status: ${tag(c?.data.status||'Draft')}</p><div class="warning">The academy must verify course prerequisites, training syllabus and any medical or aviation authority requirements before confirming admission.</div></div>`)}${subSection('Apply in three stages',`<div class="timeline"><div class="item"><strong>Select your course</strong><p>Choose an intake and preferred training location.</p></div><div class="item"><strong>Complete application</strong><p>Provide student details and supporting documents.</p></div><div class="item"><strong>Admissions decision</strong><p>Track review and obtain enrolment guidance.</p></div></div>${btn('Apply for this course','goto','green full','data-to="8"')}`)}</div>`}
function seminarBookingPage(s){let seminar=APP.items[0];return `${head(s,btn('Reserve Seat','goto','primary','data-to="5"'))}${hero('Book a Place at the Seminar','Join the next Pilot Training Seminar and receive a scannable entry ticket.','airport',btn('Register for Free','goto','gold','data-to="5"'))}<div class="grid cols-main" style="margin-top:18px">${subSection('Seminar booking',`<p><strong>Event:</strong> ${E(seminar?.title||'Pilot Training Seminar')}</p><p><strong>Date:</strong> ${fmt(seminar?.data.date||'2026-12-12')}</p><p><strong>Location:</strong> ${E(seminar?.data.venue||'Dolphin House, Harare')}</p><p><strong>Fee:</strong> FREE · Booking compulsory</p>${btn('Book a Seat Now','goto','primary full','data-to="5"')}`)}${subSection('Booking support',`<div class="help-list">${[6,26,10].map(i=>`<button data-go="${i}">${E(S(i).title)} <span>→</span></button>`).join('')}</div>`)}</div>`}
function flightPackagePage(s){return `${head(s,btn('Request a Flight Booking','goto','primary','data-to="42"'))}${hero('Your First Pilot-Seat Experience','Experience an introductory scenic flight and learn how training pathways work.','flight','')}<div class="grid cols3" style="margin-top:17px">${navTile(42,'📝','Reserve Experience','Submit your desired date and contact details')}${navTile(43,'🎟','Booking Confirmation','Use your booking reference to follow up')}${navTile(26,'🎧','Ask Admissions','Confirm flights, travel and accommodation details')}</div><div class="grid cols-main" style="margin-top:18px">${subSection('Illustrative itinerary',`<div class="timeline"><div class="item"><strong>Travel and accommodation</strong><p>Confirm dates and travel arrangements with the academy.</p></div><div class="item"><strong>Preflight orientation</strong><p>Safety briefing, introductions and experience planning.</p></div><div class="item"><strong>Scenic flight</strong><p>Experience flight from a passenger or approved pilot-seat perspective.</p></div><div class="item"><strong>Further training options</strong><p>Discuss next steps with the IrvinAero team.</p></div></div>`)}${subSection('Before booking',`<div class="warning">The advertised US$300 package, dates and remaining places are subject to confirmation. The online form only requests a reservation. No charge is processed.</div>${btn('Request Booking →','goto','green full','data-to="42"')}`)}</div>`}
function flightReviewPage(s){let flights=APP.items;return `${head(s,editorButton('flights','＋ Record a Training Flight'))}<div class="grid cols-main">${subSection('Flight record verification',tableRows(flights,'flights'))}${subSection('Instructor review workflow',`<div class="timeline"><div class="item"><strong>Submit flight record</strong><p>Capture aircraft, exercise, flight time and remarks.</p></div><div class="item"><strong>Check record accuracy</strong><p>Authorised instructor checks details and logs.</p></div><div class="item"><strong>Approve flight log</strong><p>Verified records contribute to training records.</p></div></div>${btn('Instructor Dashboard','goto','light full','data-to="46"')}`)}</div>`}
function analyticsDashboardPage(s){return `${head(s,btn('Download / Print Reports','goto','primary','data-to="62"'))}<div class="grid cols4">${metricCard('👥','students','Students')}${metricCard('🎓','applications','Applications')}${metricCard('📘','courses','Courses')}${metricCard('💰','paidRevenue','Verified revenue')}</div><div class="grid cols-main" style="margin-top:18px">${subSection('Application trends',`<div id="overview-chart">Loading trends…</div>`)}${subSection('Academy analytics',`<div class="help-list">${[31,54,62,61].map(id=>`<button data-go="${id}">${E(S(id).title)} <span>→</span></button>`).join('')}</div>`)}</div>`}
function homePage(s){let courses=APP.items.slice(0,3);return `${head(s,btn('Student Login','goto','primary','data-to="10"'))}${hero('Train for a Career<br>in Aviation','Pilot training · Cabin crew training · Professional aviation programmes and guided learning.','',btn('Explore Courses →','goto','gold','data-to="2"')+btn('Apply Now','goto','white','data-to="8"'))}<div class="grid cols3" style="margin:18px 0 22px">${navTile(2,'✈','Pilot Training','Training pathways and licences')}${navTile(2,'🎓','Cabin Crew Training','Cabin safety and service')}${navTile(4,'🎤','Seminars & Experiences','Events and flight experience')}</div><div class="grid cols-main">${subSection('Training programmes',cardList(courses,'courses'),btn('View all courses →','goto','light','data-to="2"'))}${subSection('Upcoming & important',`<div class="feed"><div class="feed-icon">🎤</div><div><strong>Pilot Training Seminar</strong><p>12 December 2026 · Dolphin House, Harare · FREE entry</p>${btn('Register free','goto','primary sm','data-to="5"')}</div></div><div class="feed"><div class="feed-icon">🛫</div><div><strong>Introductory Flight Experience</strong><p>3–7 December 2026 · promotional package information</p>${btn('View experience','goto','light sm','data-to="7"')}</div></div>`)}</div>`}
function catalog(s){let courses=APP.items.filter(c=>APP.tab==='All'||c.data.category===APP.tab);return `${head(s,btn('Apply for Training','goto','primary','data-to="8"'))}${hero('Our Aviation Courses','Explore your aviation training pathway, entry requirements and study options.','airport','')}<div class="pills" style="margin:20px 0">${['All','Pilot Training','Ratings','Cabin Crew'].map(t=>`<button class="pill ${APP.tab===t?'on':''}" data-action="tab" data-tab="${E(t)}">${E(t)}</button>`).join('')}</div><div class="grid cols3">${courses.map(c=>`<div class="card"><div style="height:110px;border-radius:11px;background:linear-gradient(#082c56a3,#06326988),url('/media/ppl-plane.webp') center/cover;margin-bottom:15px"></div><strong>${E(c.title)}</strong><p class="muted tiny" style="line-height:1.6;min-height:55px">${E(c.data.description)}</p><div class="flex space">${tag(c.data.category)}<button class="btn sm primary" data-action="chooseCourse" data-course="${E(c.title)}">View details →</button></div></div>`).join('')}</div><div class="hint" style="margin-top:18px">Course fees, official training approvals, locations and entry requirements must be confirmed with the academy before payment.</div>`}
function courseDetail(s){let selected=APP.items.find(r=>r.title===APP.course)||APP.items[0];if(!selected)return head(s)+empty('No published programme');let r=selected;return `${head(s,btn('Apply for this course','goto','green','data-to="8"'))}${hero(E(r.title),'Study theory, work with instructors, complete assessments and track practical training in your academy portal.','ppl',btn('Apply Now →','goto','gold','data-to="8"'))}<div class="grid cols4" style="margin:17px 0">${stat('⏱',r.data.duration||'Ask school','Course duration')}${stat('📘','Theory','Learning pathway')}${stat('🛩','Practical','Flight training where applicable')}${stat('💳',r.data.fee||'Enquire','Course fees')}</div><div class="grid cols-main">${subSection('About this programme',`<p class="sub" style="margin:0 0 18px">${E(r.data.description)}</p><h4>Syllabus overview</h4><p class="sub">${E(r.data.syllabus||'Contact admissions for the current approved syllabus.')}</p><div class="hint" style="margin-top:18px">Training completion does not itself issue an aviation licence or rating. Licence eligibility and examinations are governed by the applicable authority.</div>`)}${subSection('Next steps',`<div class="help-list">${[8,39,10,25].map(id=>`<button data-go="${id}">${S(id).icon} ${S(id).title}<span>→</span></button>`).join('')}</div>`)}</div>`}
function seminarPage(s){let rec=APP.items[0],d=rec?.data||{date:'2026-12-12',time:'09:00',venue:'Dolphin House, Harare',capacity:200,price:'FREE'};return `${head(s,btn('Book Your Seat →','goto','primary','data-to="5"'))}${hero('Pilot Training Seminar','Understand pilot careers, study requirements and pathways. Ask instructors questions and explore your options.','airport',btn('Register for Free','goto','gold','data-to="5"'))}<div class="grid cols4" style="margin:18px 0">${stat('📆',fmt(d.date),'Seminar date')}${stat('⏰',d.time||'09:00','Start time')}${stat('🎟',d.price||'FREE','Entry')}${stat('👥',d.capacity||'Limited','Seat capacity')}</div><div class="grid cols-main">${subSection('Event information',`<div class="stack"><p><strong>Venue:</strong> ${E(d.venue)}</p><p><strong>What to expect:</strong> Career guidance, pilot training pathways, practical training orientation and questions with instructors.</p><p class="muted tiny">Advance booking is required; tickets are issued after registration.</p>${btn('Register now →','goto','primary full','data-to="5"')}</div>`)}${subSection('After registration',`<div class="timeline"><div class="item"><strong>Reserve your place</strong><p>Provide name and contact information.</p></div><div class="item"><strong>Receive booking reference</strong><p>Save your verification code safely.</p></div><div class="item"><strong>Present your QR ticket</strong><p>Academy staff confirm your attendance.</p></div></div>`)}</div>`}
function seminarRegistration(s){return `${head(s)}<div class="grid cols-main"><section class="card"><h3 class="card-title">Reserve your Pilot Training Seminar seat</h3><div class="hint" style="margin-bottom:20px">Saturday 12 December 2026 · 09:00 · FREE ENTRY · Dolphin House, Harare</div><form id="seminar-form"><div class="form-grid">${formFields('tickets',{date:'2026-12-12'})}</div><label class="flex tiny" style="margin-bottom:14px"><input type="checkbox" required> I confirm the information is accurate and agree to receive event booking communications.</label><button class="btn primary full" type="submit">Confirm Free Booking →</button></form></section>${subSection('What happens next?',`<div class="timeline"><div class="item"><strong>Registration saved</strong><p>Your booking is stored in the academy database.</p></div><div class="item"><strong>Ticket generated</strong><p>Receive an accessible QR ticket and verification reference.</p></div><div class="item"><strong>Venue check-in</strong><p>Present your QR ticket for staff check-in.</p></div></div>`)}</div>`}
function ticketPage(s){let cached=localStorage.getItem('irvin_last_ticket');let info=cached?JSON.parse(cached):null;return `${head(s)}<div class="grid cols-main">${subSection('Your seminar ticket',info?`<div class="success">Your registration reference is <strong>${E(info.id.toUpperCase())}</strong>.</div><div id="ticket-data" style="padding:20px;text-align:center"><div class="qr"><img alt="Seminar check-in QR code" src="/api/ticket-qr?id=${encodeURIComponent(info.id)}&code=${encodeURIComponent(info.code)}"></div><p><strong>Verification code:</strong> ${E(info.code)}</p><p class="tiny muted">Show this QR code at the venue.</p></div><div class="flex">${btn('Print Ticket','print','primary')}${btn('New registration','goto','light','data-to="5"')}</div>`:`${empty('No recent ticket on this device','Enter your booking reference and verification code to retrieve it.')}`)}${subSection('Retrieve a booking',`<form id="lookup-form" data-kind="tickets"><div class="field"><label>Booking reference</label><input class="input" name="id" placeholder="Booking ID" required></div><div class="field"><label>Verification code</label><input class="input" name="code" placeholder="Code from confirmation" required></div><button class="btn primary full" type="submit">Retrieve ticket</button></form><p class="muted tiny">Booking references and codes are displayed immediately after completing registration.</p>`)}</div>`}
function flightPage(s){return `${head(s,btn('Book Your Experience','goto','primary','data-to="42"'))}${hero('Introductory Flight Experience','Get an introduction to aviation with a pilot-seat experience, accommodation and return transport according to the confirmed programme.','flight',btn('Book Your Experience →','goto','gold','data-to="42"'))}<div class="grid cols4" style="margin:18px 0">${stat('📅','3–7 Dec','Proposed 2026 dates')}${stat('💵','US$300','Promotional package')}${stat('🏨','2 nights','Accommodation')}${stat('🎟','10','Maximum participants')}</div><div class="grid cols-main">${subSection('Package includes',`<div class="stack">${['Return transport to Johannesburg','Two nights’ accommodation','Scenic flight and pilot-seat experience','Travel guidance and scheduling'].map(x=>`<div class="flex"><span style="color:var(--green)">✔</span> ${x}</div>`).join('')}</div><div class="warning" style="margin-top:20px">Dates, availability, permissions, travel arrangements and the final cost must be confirmed with IrvinAero before any payment.</div>`)}${subSection('Booking steps',`<div class="timeline"><div class="item"><strong>Submit your details</strong><p>Choose date and number of participants.</p></div><div class="item"><strong>Academy confirms availability</strong><p>Staff review booking and practical arrangements.</p></div><div class="item"><strong>Receive payment instructions</strong><p>Payments are not automatically collected in this staging platform.</p></div></div>`)}</div>`}
function applicationPage(s){let draft=APP.draft.application||{};let courseopts=['Private Pilot Licence (PPL)','Commercial Pilot Licence (CPL)','Night Rating','Instrument Rating','Flight Instructor Training','Cabin Crew Training'];return `${head(s)}<div class="grid cols-main">${subSection('Apply for a training programme',`<div class="tags"><span class="tag active">1 · Personal</span><span class="tag">2 · Course</span><span class="tag">3 · Review & Submit</span></div><form id="application-form"><div class="field"><label>Applicant name *</label><input class="input" name="name" value="${E(draft.name||APP.user?.name||'')}" required></div><div class="form-grid"><div class="field"><label>Email *</label><input class="input" type="email" name="email" value="${E(draft.email||APP.user?.email||'')}" required></div><div class="field"><label>Phone number *</label><input class="input" type="tel" name="phone" value="${E(draft.phone||'')}" required></div><div class="field"><label>Programme *</label><select class="select" name="course" required><option value="">Choose programme…</option>${courseopts.map(x=>`<option ${x===(draft.course||APP.course)?'selected':''}>${E(x)}</option>`).join('')}</select></div><div class="field"><label>Preferred intake</label><input class="input" name="intake" placeholder="e.g. February 2027" value="${E(draft.intake||'')}"></div><div class="field"><label>Highest academic qualification</label><input class="input" name="qualification" value="${E(draft.qualification||'')}"></div></div><div class="field"><label>Additional information</label><textarea class="textarea" name="notes">${E(draft.notes||'')}</textarea></div><label class="flex tiny" style="margin-bottom:14px"><input type="checkbox" required> I confirm my details are accurate and consent to academy contact.</label><button class="btn primary full" type="submit">Review & Submit Application →</button></form>`)}${subSection('Admission checklist',`<div class="stack">${['Select a training programme','Complete your details','Submit supporting documents if required','Receive a reference and verification code','Track your application online'].map(x=>`<div class="flex"><span class="badge blue">✓</span><span style="font-size:12px">${x}</span></div>`).join('')}</div><div class="hint" style="margin-top:18px">Admission acceptance is conditional on the academy verifying the relevant course requirements.</div>`)}</div>`}
function trackingPage(s){return `${head(s)}<div class="grid cols-main">${subSection('Track your application',`<form id="lookup-form" data-kind="applications"><div class="field"><label>Application reference</label><input class="input" name="id" placeholder="Enter reference ID" required></div><div class="field"><label>Verification code</label><input class="input" name="code" placeholder="Code from submission" required></div><button class="btn primary full" type="submit">Check Status →</button></form><div id="lookup-result"></div>`)}${subSection('Admission steps',`<div class="timeline"><div class="item"><strong>Submitted</strong><p>Application received by the academy.</p></div><div class="item"><strong>Under review</strong><p>Admission team verifies documents and eligibility.</p></div><div class="item"><strong>Decision</strong><p>Receive formal acceptance or next-step requests.</p></div><div class="item"><strong>Enrolment</strong><p>Follow payment and orientation instructions.</p></div></div>`)}</div>`}
function loginPage(s){return `${head(s)}<div class="card login-box"><div class="brand-light"><span style="font-size:35px">✈</span><div><strong style="font-size:20px;color:#0b386d">IRVINAERO</strong><div class="tiny muted">AVIATION · ACADEMY</div></div></div>${APP.user?`<h2>Welcome, ${E(APP.user.name)}</h2><p class="muted">You are signed in as <strong>${E(role())}</strong>.</p><div class="grid cols2">${btn('Student Portal','goto','primary','data-to="11"')}${btn('Admin Portal','goto','light','data-to="50"')}${btn('Log out','logout','red')}</div>`:`<h2>Welcome Back</h2><p class="muted tiny">Sign in to your IrvinAero account.</p><form id="login-form"><div class="field"><label>Email</label><input class="input" type="email" name="email" required placeholder="your@email.com"></div><div class="field"><label>Password</label><input class="input" type="password" name="password" required placeholder="Enter your password"></div><button class="btn primary full" type="submit">Log In →</button></form><p class="tiny muted">New student? <a href="javascript:void(0)" data-action="register" style="color:var(--blue)">Create an account</a> · <a href="javascript:void(0)" data-action="forgot" style="color:var(--blue)">Forgot password?</a></p>${APP.settings.demo?`<div class="auth-demo"><p>STAGING ACCOUNTS · Shared demo password: <strong>Demo2026!</strong></p><div class="roles">${['student','instructor','admissions','finance','admin','ceo'].map(r=>`<button data-action="demoLogin" data-role="${r}">${r}</button>`).join('')}</div></div>`:''}`}</div>`}
function loginGate(s){return `${head(s)}<div class="grid cols-main">${subSection('Sign in to access this screen',`<p class="sub">This section contains student or academy data and requires an authorised account.</p><div style="margin-top:20px">${btn('Go to login →','goto','primary','data-to="10"')}</div>`)}${subSection('Available without login',`<div class="help-list">${[1,2,4,5,7,8,9].map(id=>`<button data-go="${id}">${E(S(id).title)} <span>→</span></button>`).join('')}</div>`)}</div>`}
function myCourses(s){let cs=APP.items;return `${head(s,btn('Browse Courses','goto','primary','data-to="2"'))}${stat('📚',cs.length,'Available study programmes')}<div class="grid cols3" style="margin-top:18px">${cs.map((c,i)=>`<div class="card"><div class="course-pic" style="width:100%;height:110px;background:linear-gradient(130deg,#0928558a,#0a4e97bb),url('/media/ppl-plane.webp') center/cover">✈</div><h3>${E(c.title)}</h3><p class="muted tiny">${E(c.data.description)}</p><div class="flex space">${tag(c.data.status)}<button class="btn sm primary" data-action="chooseCourse" data-course="${E(c.title)}">Explore →</button></div></div>`).join('')}</div><div class="hint" style="margin-top:16px">Demo lesson access is for platform evaluation; actual enrolment-based access must be enforced before production.</div>`}
function lessonPage(s){let l=APP.items[0];let lessons=APP.items;if(!l)return `${head(s)}${empty('No lessons published','Instructors can add course lessons from Content Manager.')}`;let selected=lessons.find(x=>x.id===APP.selected)||l;return `${head(s,btn('View study materials','goto','light','data-to="52"'))}<div class="grid cols-main"><section class="card"><div class="lesson-player"><button data-action="lessonPlay" title="Open lesson content">▶</button><div class="play-caption">${E(selected.title)}</div></div><div style="margin-top:22px"><div class="kicker">CURRENT LESSON · ${E(selected.data.course||'Aviation Theory')}</div><h2>${E(selected.title)}</h2><p class="sub" style="margin:10px 0 20px">${E(selected.data.content||'Study the approved lesson content from your instructor.')}</p><div class="flex" style="flex-wrap:wrap">${btn('Mark as Complete ✓','lessonComplete','green',`data-id="${selected.id}"`)}${btn('Save Lesson Note','lessonNote','light',`data-id="${selected.id}"`)}${btn('Next Lesson →','nextLesson','primary',`data-id="${selected.id}"`)}</div></div></section>${subSection('Lesson list',lessons.map((x,i)=>`<button class="course-card" style="width:100%;text-align:left;margin:7px 0;${x.id===selected.id?'border-color:#0b6be3;background:#eef5ff':''}" data-action="selectLesson" data-id="${x.id}"><div class="course-pic" style="width:40px;height:39px;font-size:17px">${i+1}</div><div><strong>${E(x.title)}</strong><p>${E(x.data.duration||'Lesson')}</p></div></button>`).join(''))}</div>`}
function assignmentPage(s){return `${head(s,btn('Submit Assignment','submitAssignment','primary'))}<div class="grid cols-main">${subSection('Assigned work',cardList(APP.items,'assignments'))}${subSection('How to submit',`<div class="timeline"><div class="item"><strong>Select the assignment</strong><p>Check the instructions and due date.</p></div><div class="item"><strong>Submit your response</strong><p>Enter your response and an optional document link.</p></div><div class="item"><strong>Instructor marking</strong><p>Receive results and feedback after review.</p></div></div>`)}</div>`}
function quizPage(s,isExam){let quizTitle=isExam?'Timed Examination':'Practice Quiz';return `${head(s,isExam?'':btn('New question','new','light','data-kind="questions"'))}<div class="grid cols-main">${subSection(quizTitle,`<div class="flex space" style="margin-bottom:16px"><span class="badge blue">Aviation Theory · 3 questions</span>${isExam?'<span class="exam-timer" id="exam-clock">20:00</span>':'<span class="badge green">Practice mode</span>'}</div><div id="quiz-area"><div class="hint">${isExam?'Your examination will begin once you select Start. Answer all questions before submitting.':'Review fundamentals and receive instant results.'}</div><div style="margin-top:20px">${btn(isExam?'Start Timed Exam':'Start Practice Test','startQuiz','primary',`data-exam="${isExam?'1':'0'}"`)}</div></div>`)}${subSection('Assessment guidance',`<div class="stack"><p class="tiny muted">Questions come from the approved local question bank. The platform automatically grades multiple-choice items.</p><p class="tiny muted">For formal aviation licensing examinations, confirm the applicable regulator and approved testing requirements.</p>${btn('View Results','goto','light','data-to="16"')}${management()?btn('Manage Questions','goto','light','data-to="48"'):''}</div>`)}</div>`}
function resultsPage(s){let items=APP.items;return `${head(s)}<div class="grid cols3">${stat('🏆',items.length?'Completed':'—','Recorded assessments')}${stat('📊',items.length?Math.round(items.reduce((a,x)=>a+Number(x.data.percent||x.data.score||0),0)/items.length)+'%':'—','Average result')}${stat('✅',items.filter(x=>x.data.passed).length,'Assessments passed')}</div><section class="card" style="margin-top:18px"><h3 class="card-title">My results</h3>${tableRows(items,'grades')}</section>`}
function calendarPage(s){let days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];let cls=APP.items;return `${head(s,btn('Class List','goto','light','data-to="18"'))}<div class="grid cols-main">${subSection('December 2026',`<div class="calendar">${days.map(x=>`<div class="cal-head">${x}</div>`).join('')}${Array.from({length:35},(_,i)=>`<button class="cal-day ${cls.some(c=>Number(String(c.data.start||'').slice(8,10))===i+1)?'has':''}" data-action="calendarDay" data-day="${i+1}">${i<31?i+1:''}</button>`).join('')}</div>`)}${subSection('Scheduled activities',cardList(cls,'classes'))}</div>`}
function livePage(s){return `${head(s)}<div class="grid cols-main">${subSection('Upcoming live sessions',APP.items.map(c=>`<div class="feed"><div class="feed-icon">📹</div><div style="flex:1"><strong>${E(c.title)}</strong><p>${fmt(c.data.start)} · ${E(c.data.location||'Classroom')}</p>${btn('Class details','details','light sm',`data-id="${c.id}"`)} ${btn('Join class','joinClass','primary sm',`data-id="${c.id}"`)}</div></div>`).join('')||empty('No live classes scheduled'))}${subSection('Classroom guidance',`<div class="warning">Zoom, Meet and video hosting are not connected. Staff can add an actual authorised classroom URL to each class record; until then the Join button explains the next step.</div>`)}</div>`}
function attendancePage(s){return `${head(s,editorButton('attendance','＋ Record Attendance'))}<div class="grid cols3">${stat('✅',APP.items.filter(x=>x.data.status==='Present').length,'Present records')}${stat('📅',APP.items.length,'Total attendance records')}${stat('⏳',APP.items.filter(x=>x.data.status!=='Present').length,'Other attendance')}</div><section class="card" style="margin-top:18px">${tableRows(APP.items,'attendance')}</section>`}
function logbookPage(s){let rows=APP.items;let total=rows.reduce((sum,r)=>sum+Number(r.data.solo||0)+Number(r.data.dual||0),0);return `${head(s,editorButton('flights','＋ Add Flight Record'))}<div class="grid cols3">${stat('✈',total.toFixed(1)+' hrs','Total recorded flight time')}${stat('👨‍✈️',rows.reduce((n,r)=>n+Number(r.data.dual||0),0).toFixed(1),'Dual instruction hours')}${stat('🛫',rows.reduce((n,r)=>n+Number(r.data.solo||0),0).toFixed(1),'Solo flight hours')}</div><div class="grid cols-main" style="margin-top:17px">${subSection('Recent flight records',tableRows(rows,'flights'))}${subSection('Safety & verification',`<div class="warning">Student-submitted flight records require authorised instructor verification. Do not use these staging records as regulatory flight logbook originals.</div>${btn('Aircraft schedule','goto','light full','data-to="45"')}`)}</div>`}
function paymentPage(s){return `${head(s,editorButton('payments','＋ Submit Payment Reference'))}<div class="grid cols-main">${subSection('Submit a tuition payment',`<div class="hero subhero airport" style="margin-bottom:16px"><div class="hero-content"><h2>Simple & traceable payments</h2><p>Submit a transaction reference for verification by the finance office.</p></div></div><div class="warning">EcoCash and card gateways are <strong>not connected</strong>. Do not enter PINs or card details. No money is charged by this site.</div><div style="margin-top:16px">${editorButton('payments','Add Payment Reference')}</div>`)}${subSection('Payment history',tableRows(APP.items,'payments'))}</div>`}
function profilePage(s){return `${head(s)}<div class="grid cols-main">${subSection('Account details',APP.user?`<div class="flex"><div class="avatar" style="width:77px;height:77px;font-size:24px">${E(APP.user.name.split(' ').map(x=>x[0]).join(''))}</div><div><strong style="font-size:21px">${E(APP.user.name)}</strong><p class="muted tiny">${E(APP.user.email)}</p>${tag(APP.user.role)}</div></div><div class="stack" style="margin-top:25px"><p><strong>Name:</strong> ${E(APP.user.name)}</p><p><strong>Email:</strong> ${E(APP.user.email)}</p><p><strong>Role:</strong> ${E(APP.user.role)}</p></div>${btn('Edit Profile','editProfile','primary')} ${btn('Change Password','goto','light','data-to="30"')}`:empty('Log in to view profile'))}${subSection('Academy actions',`<div class="help-list">${quickLinks(s)}</div>`)}</div>`}
function messagesPage(s){return `${head(s,editorButton('messages','＋ New Message'))}<div class="grid cols-main">${subSection('Inbox & sent messages',APP.items.length?APP.items.map(r=>`<div class="feed"><div class="feed-icon">💬</div><div style="flex:1"><strong>${E(r.title)}</strong><p>${E(short(r.data.message))}</p><div class="tiny muted">To: ${E(r.data.recipient||'Academy')} · ${fmt(r.created)}</div></div><button class="rowbtn" data-action="details" data-id="${r.id}">Open</button></div>`).join(''):empty('No messages yet','Use New Message to contact the academy.'))}${subSection('Support channels',`<div class="help-list">${[26,63,10].map(id=>`<button data-go="${id}">${E(S(id).title)}<span>→</span></button>`).join('')}</div><div class="hint" style="margin-top:12px">This staging app stores in-app messages. External WhatsApp, email and SMS dispatch require separate integrations.</div>`)}</div>`}
function supportPage(s){return `${head(s,editorButton('support','＋ New Support Ticket'))}<div class="grid cols-main">${subSection('My support requests',tableRows(APP.items,'support'))}${subSection('Popular questions',`<div class="help-list">${['How do I enrol?','How do I submit an assignment?','How is my tuition payment verified?','How do I retrieve my seminar ticket?'].map((q,i)=>`<button data-action="faq" data-faq="${i}">${q}<span>→</span></button>`).join('')}</div>`)}</div>`}
function uploadPage(s){return `${head(s)}<div class="grid cols-main">${subSection('Document library',`<div class="warning" style="margin-bottom:15px">Upload only documents you are authorised to share. This staging platform stores private uploads on its local server; production storage requires secure cloud backups and retention policies.</div><div class="field"><label>Choose a PDF or image (maximum 3 MB)</label><input class="input" type="file" id="doc-upload" accept="image/*,.pdf,.doc,.docx"></div><div class="flex">${btn('Upload & Save Document','upload','primary')}${editorButton('documents','Add Document Details')}</div><div style="margin-top:18px">${tableRows(APP.items,'documents')}</div>`)}${subSection('Recommended admissions documents',`<div class="stack">${['National identity or passport','Academic qualifications','Applicable medical documentation','Course application form','Passport-sized photograph'].map(t=>`<div class="flex"><span class="badge blue">📄</span><span class="tiny">${t}</span></div>`).join('')}</div>`)}</div>`}
function progressPage(s){return `${head(s)}<div class="grid cols3">${stat('📘','7','Sample theory lessons')}${stat('🎓','70%','Example passing threshold')}${stat('🛩','0h','Verified flight hours (demo)')}</div><div class="grid cols-main" style="margin-top:16px">${subSection('Training performance overview',`${graph()}<div class="stack" style="margin-top:18px">${['Air Law','Meteorology','Navigation','Flight Planning','Principles of Flight'].map((n,i)=>`<div><div class="flex space tiny"><strong>${n}</strong><span>${[100,75,60,85,48][i]}%</span></div><div class="progress" style="margin-top:6px"><span style="width:${[100,75,60,85,48][i]}%"></span></div></div>`).join('')}</div>`)}${subSection('Training activities',`<div class="help-list">${[12,13,14,15,16,20].map(id=>`<button data-go="${id}">${E(S(id).title)} <span>→</span></button>`).join('')}</div>`)}</div>`}
function accountPage(s){return `${head(s)}<div class="grid cols-main">${subSection('Account security',`<form id="password-form"><div class="field"><label>Current password</label><input class="input" type="password" name="current" required></div><div class="field"><label>New password (10+ characters)</label><input class="input" type="password" name="new" required minlength="10"></div><button class="btn primary" type="submit">Update Password</button></form><div class="flex" style="margin-top:25px">${btn('Log Out','logout','red')}${btn('My Profile','goto','light','data-to="24"')}</div>`)}${subSection('Preferences & privacy',`<div class="help-list">${['Manage session security','Change password','Review communication preferences','Contact support'].map((s,i)=>`<button data-action="settingInfo" data-info="${i}">${s} <span>→</span></button>`).join('')}</div><div class="hint" style="margin-top:14px">Two-factor authentication, external SMS delivery and self-service account recovery are not connected in this staging version.</div>`)}</div>`}
function admissionsPage(s){return `${head(s,editorButton('applications','＋ New Application'))}<div class="grid cols-main">${subSection('Admission applications',tableRows(APP.items,'applications'))}${subSection('Admission workflow',`<div class="timeline"><div class="item"><strong>Application submitted</strong><p>Capture personal details and training choice.</p></div><div class="item"><strong>Documents reviewed</strong><p>Staff inspect supporting evidence.</p></div><div class="item"><strong>Admission decision</strong><p>Approve, request corrections or reject.</p></div><div class="item"><strong>Enrolment</strong><p>Issue instructions for the relevant intake.</p></div></div>${btn('Open intake management','goto','light full','data-to="39"')}`)}</div>`}
function intakesPage(s){return `${head(s,editorButton('intakes','＋ Create New Intake'))}<div class="grid cols-main">${subSection('Published intake dates',cardList(APP.items,'intakes'))}${subSection('Training timetable',`<div class="help-list">${[17,18,45].map(i=>`<button data-go="${i}">${E(S(i).title)}<span>→</span></button>`).join('')}</div><div class="hint" style="margin-top:14px">Administrators can add intakes, dates, enrolment caps and availability statuses.</div>`)}</div>`}
function bookingForm(s){return `${head(s)}<div class="grid cols-main">${subSection('Book Introductory Flight Experience',`<div class="hint" style="margin-bottom:14px">Preferred experience dates: 3–7 December 2026. This is a booking request, not a charge or a confirmed flight slot.</div><form id="booking-form">${formFields('bookings',{preferredDate:'2026-12-03',participants:'1'})}<label class="flex tiny"><input type="checkbox" required> I understand the booking must be reviewed and confirmed by academy staff.</label><div style="margin-top:18px"><button class="btn primary full" type="submit">Submit Booking Request →</button></div></form>`)}${subSection('Flight experience',`<div class="stack"><strong>Included in the advertised package:</strong>${['Scenic flight','Pilot-seat experience','Two nights’ accommodation','Return transport (subject to confirmation)'].map(t=>`<div class="flex"><span style="color:var(--green)">✓</span> ${t}</div>`).join('')}</div><div class="warning" style="margin-top:18px">Booking approval and package finalisation require an actual academy administrator. Avoid submitting sensitive travel documents in this public form.</div>`)}</div>`}
function flightConfirmation(s){let last=localStorage.getItem('irvin_last_booking');let info=last?JSON.parse(last):null;return `${head(s)}<div class="grid cols-main">${subSection('Booking request receipt',info?`<div class="success">✓ Booking request successfully saved.</div><div class="stack" style="margin:18px 0"><p><strong>Reference:</strong> ${E(info.id.toUpperCase())}</p><p><strong>Verification code:</strong> ${E(info.code)}</p><p><strong>Status:</strong> ${tag('Pending')}</p></div><div class="flex">${btn('Print Confirmation','print','primary')}${btn('Return to Experience','goto','light','data-to="41"')}</div>`:empty('No recent booking found','Book an introductory flight experience to receive a reference.'))}${subSection('Retrieve booking request',`<form id="lookup-form" data-kind="bookings"><div class="field"><label>Booking reference</label><input class="input" name="id" required></div><div class="field"><label>Verification code</label><input class="input" name="code" required></div><button class="btn primary full" type="submit">Check Booking Status</button></form><div id="lookup-result"></div>`)}</div>`}
function aircraftSchedule(s){return `${head(s,btn('Record a flight','goto','primary','data-to="20"'))}<div class="grid cols-main">${subSection('Aircraft availability',APP.items.map(a=>`<div class="feed"><div class="feed-icon">🛩</div><div style="flex:1"><strong>${E(a.title)}</strong><p>Next inspection: ${fmt(a.data.nextInspection)} · Sample fleet data</p>${tag(a.data.status)}</div>${btn('Details','details','light sm',`data-id="${a.id}"`)}</div>`).join(''))}${subSection('Training and scheduling',`<div class="help-list">${[17,18,20,58,59].map(i=>`<button data-go="${i}">${E(S(i).title)}<span>→</span></button>`).join('')}</div><div class="warning" style="margin-top:14px">Aircraft availability requires actual fleet and airworthiness data before operational use.</div>`)}</div>`}
function instructorPage(s){return `${head(s,btn('Create Class','goto','primary','data-to="17"'))}<div class="grid cols4">${stat('📚',APP.items.length,'Scheduled classes')}${stat('📝','→','Assignments to mark')}${stat('✈','→','Flight records')}${stat('✅','→','Competency approvals')}</div><div class="grid cols-main" style="margin-top:18px">${subSection('Instructor teaching schedule',cardList(APP.items,'classes'))}${subSection('Instructor shortcuts',`${btn('Mark Student Assignments','collection','primary full','data-kind="submissions"')}${btn('Competency Sign-offs','collection','light full','data-kind="competencies"')}<div class="help-list" style="margin-top:12px">${[47,48,13,20,17,25].map(i=>`<button data-go="${i}">${E(S(i).title)} <span>→</span></button>`).join('')}</div>`)}</div>`}
function studentDirectory(s){return `${head(s)}<div class="grid cols-main">${subSection('Academy students and applications',`<div id="students-list">Loading student directory…</div>`)}${subSection('Directory tools',`<div class="help-list">${[31,32,36,19,16].map(i=>`<button data-go="${i}">${E(S(i).title)}<span>→</span></button>`).join('')}</div><div class="hint" style="margin-top:16px">View names and records according to role permissions. The live student directory requires authorised admissions records.</div>`)}</div>`}
function builderPage(s){return `${head(s,editorButton('questions','＋ Add New Question'))}<div class="grid cols-main">${subSection('Assessment question bank',tableRows(APP.items,'questions'))}${subSection('Question builder guidance',`<div class="stack"><div class="hint">Each question may have four answer options separated by <strong>|</strong>; the correct answer index starts at 0.</div><p class="tiny muted">Example: Ailerons | Elevator | Rudder | Flaps</p><p class="tiny muted">Correct answer index: 2</p><div class="help-list">${[14,15,53,16].map(i=>`<button data-go="${i}">${E(S(i).title)}<span>→</span></button>`).join('')}</div></div>`)}</div>`}
function reportsPage(s){return `${head(s,btn('Print Current Report','print','primary'))}<div class="grid cols4">${metricCard('👥','students','Registered students')}${metricCard('💰','paidRevenue','Verified revenue')}${metricCard('🎓','gradePassRate','Assessment pass rate')}${metricCard('🛩','verifiedFlightHours','Verified flight hours')}</div><div class="grid cols-main" style="margin-top:18px">${subSection('Application activity',`<div id="overview-chart">Loading application history…</div>`)}${subSection('Available reports',`<div class="help-list">${['Student enrolment report','Examination results report','Course performance report','Attendance report','Verified payment summary','Flight training progress report'].map(t=>`<button data-action="report" data-report="${E(t)}">📊 ${E(t)}<span>Print →</span></button>`).join('')}</div><div class="hint" style="margin-top:14px">Real dashboard totals must come from verified academy data. No fictional financial totals are presented as actuals.</div>`)}</div>`}
function adminPage(s){let count=APP.items.length;return `${head(s)}<div class="grid cols4">${metricCard('🎓','applications','Applications')}${metricCard('👥','students','Registered students')}${metricCard('🎟','seminarBookings','Seminar bookings')}${stat('🔒','On','Audit logging')}</div>${hero('Academy Control Centre','Admissions, lessons, payments, certificates, seminars, fleet operations and executive controls in one place.','airport','')}<div class="grid cols3" style="margin-top:18px">${[[31,'🎓','Applications'],[52,'📚','Course Content'],[53,'📝','Examinations'],[54,'💳','Finance'],[55,'🏅','Certificates'],[56,'🎤','Seminars'],[57,'🎟','QR Check-in'],[58,'🛩','Fleet'],[51,'👥','Staff'],[60,'⚙','Integrations'],[62,'📈','Reports'],[64,'🛡','Security']].map(([id,ico,n])=>navTile(id,ico,n,S(id).description)).join('')}</div>`}
function staffPage(s){return `${head(s,btn('＋ Create Staff Account','createUser','primary'))}<div class="grid cols-main">${subSection('Authorised system users',`<div id="users-list"><div class="hint">Loading authorised user directory…</div></div>`)}${subSection('Role-based permissions',`<div class="stack">${['Admin / CEO — Platform administration','Admissions — Applications and seminar registration','Finance — Payments and refunds','Instructor — Lessons, marking and flight reviews','Student — Own personal records'].map(t=>`<div class="flex">${tag(t.split(' — ')[0])}<span class="tiny">${E(t.split(' — ')[1])}</span></div>`).join('')}</div><div class="warning" style="margin-top:16px">Only authorised administrators may create accounts, change roles or issue temporary passwords. Share temporary passwords securely and require users to change them.</div>`)}</div>`}
function contentPage(s){return `${head(s,editorButton('lessons','＋ Add Lesson'))}<div class="grid cols-main">${subSection('Learning modules and lessons',tableRows(APP.items,'lessons'))}${subSection('Manage content',`<div class="help-list">${[2,12,48,53].map(id=>`<button data-go="${id}">${E(S(id).title)}<span>→</span></button>`).join('')}</div>${btn('Add Study Resource','new','light full','data-kind="resources"')} ${btn('View Study Resources','collection','white full','data-kind="resources"')}`)}</div>`}
function examManager(s){return `${head(s,editorButton('exams','＋ Create Exam'))}<div class="grid cols-main">${subSection('Examinations',tableRows(APP.items,'exams'))}${subSection('Examination operations',`<div class="help-list">${[48,14,15,16,52].map(id=>`<button data-go="${id}">${E(S(id).title)} <span>→</span></button>`).join('')}</div><div class="warning" style="margin-top:16px">This module provides internal theory assessment. Formal licensing examination protocols require external approval.</div>`)}</div>`}
function financePage(s){let rows=APP.items;let pend=rows.filter(r=>r.data.status==='Pending verification');let paid=rows.filter(r=>r.data.status==='Paid');let sum=paid.reduce((a,r)=>a+Number(r.data.amount||0),0);return `${head(s,editorButton('payments','＋ Add Payment'))}<div class="grid cols4">${stat('💵','US$'+sum.toLocaleString(),'Verified local payments')}${stat('⏳',pend.length,'Unverified submissions')}${stat('✓',paid.length,'Approved payments')}${stat('🧾',rows.length,'Total payment records')}</div><div class="grid cols-main" style="margin-top:18px">${subSection('Payment reconciliation',tableRows(rows,'payments'))}${subSection('Finance actions',`<div class="help-list">${[[22,'Invoices & receipts'],[54,'Payment reconciliation'],[62,'Financial reports']].map(([id,t])=>`<button data-go="${id}">${t} <span>→</span></button>`).join('')}</div><div style="margin-top:14px">${editorButton('refunds','＋ New Refund Request')} ${btn('View Refund Requests','collection','light','data-kind="refunds"')}</div><div class="warning" style="margin-top:12px">Only a finance-authorised account can approve submitted payments. Automatic EcoCash verification is not integrated.</div>`)}</div>`}
function certManager(s){return `${head(s,editorButton('certificates','＋ Issue Certificate'))}<div class="grid cols-main">${subSection('Certificate register',tableRows(APP.items,'certificates'))}${subSection('Issuance rules',`<div class="stack">${['Check authorised student completion','Confirm required assessment results','Ensure training sign-offs are approved','Issue the correctly labelled academy certificate','Provide printable PDF and verification reference'].map(t=>`<div class="flex"><span class="badge blue">✓</span> ${t}</div>`).join('')}</div><div class="warning" style="margin-top:14px">Academy-issued certificates are not pilot licences or aviation ratings. Regulators control formal licensing.</div>`)}</div>`}
function seminarManager(s){return `${head(s,editorButton('seminars','＋ Create Seminar'))}<div class="grid cols-main">${subSection('Seminars',cardList(APP.items,'seminars'))}${subSection('Event administration',`<div class="help-list">${[4,5,6,56,57].filter(i=>i!==s.id).map(i=>`<button data-go="${i}">${E(S(i).title)} <span>→</span></button>`).join('')}</div><div class="hint" style="margin-top:12px">To check attendee QR codes, go to QR Check-in and enter the unique ticket reference and verification code.</div>`)}</div>`}
function checkinPage(s){return `${head(s)}<div class="grid cols-main">${subSection('Verify and check in a seminar ticket',`<form id="checkin-form"><div class="field"><label>Ticket reference</label><input class="input" name="id" placeholder="Paste ticket ID" required></div><div class="field"><label>Verification code</label><input class="input" name="code" placeholder="Enter code from attendee ticket" required></div><button type="submit" class="btn primary full">Verify Ticket →</button></form><div style="margin-top:12px">${btn('📷 Scan QR Using Camera','scanQR','light full')}</div><video id="qr-video" muted playsinline style="display:none;width:100%;margin-top:12px;border-radius:10px"></video><div id="checkin-result"></div><div class="hint" style="margin-top:14px">Check-in verification requires access to the original ticket reference and code. Duplicate check-ins are shown as already present.</div>`)}${subSection('Seminar operations',`<div class="help-list">${[56,4,5,6].map(i=>`<button data-go="${i}">${E(S(i).title)}<span>→</span></button>`).join('')}</div>`)}</div>`}
function fleetPage(s){return `${head(s,editorButton('aircraft','＋ Add Aircraft'))}<div class="grid cols3">${stat('✈',APP.items.length,'Fleet records')}${stat('✓',APP.items.filter(x=>x.data.status==='Available').length,'Available in records')}${stat('🛠',APP.items.filter(x=>/maintenance/i.test(x.data.status||'')).length,'Maintenance status')}</div><div class="grid cols-main" style="margin-top:18px">${subSection('Aircraft & fleet register',cardList(APP.items,'aircraft'))}${subSection('Fleet actions',`<div class="help-list">${[45,20,59].map(i=>`<button data-go="${i}">${E(S(i).title)} <span>→</span></button>`).join('')}</div><div class="warning" style="margin-top:15px">Aircraft records in this demo are placeholders and must be replaced with the academy’s verified registrations and maintenance status.</div>`)}</div>`}
function maintenancePage(s){return `${head(s,editorButton('maintenance','＋ Add Maintenance Log'))}<div class="grid cols-main">${subSection('Scheduled maintenance and inspections',tableRows(APP.items,'maintenance'))}${subSection('Maintenance & safety workflow',`<div class="timeline"><div class="item"><strong>Schedule inspection</strong><p>Record the responsible aircraft and due date.</p></div><div class="item"><strong>Take aircraft out of service</strong><p>Update availability when work is due or in progress.</p></div><div class="item"><strong>Record completion</strong><p>Verify with the authorised maintenance organisation.</p></div></div><div class="warning">The app cannot independently determine airworthiness or certify maintenance completion.</div>`)}</div>`}
function settingsPage(s){return `${head(s)}<div class="grid cols-main">${subSection('Platform configurations',`<div class="grid cols2">${[['⚙','General Settings','Academy details'],['🎨','Branding & Logo','Colours and brand assets'],['✉','Email & SMS','Not connected'],['💬','WhatsApp Integration','Not connected'],['💳','Payments (EcoCash / Bank)','Manual verification only'],['☁','Backup & Storage','Local server storage'],['🛡','Permissions & Security','Role-based access'],['🌐','Website & Portal','Configured locally']].map(([i,a,b])=>`<button class="tile" data-action="integration" data-integration="${E(a)}"><span class="emoji">${i}</span><strong>${a}</strong><small>${b}</small></button>`).join('')}</div>`)}${subSection('Integration statuses',`<div class="stack">${['EcoCash — NOT CONNECTED','Email / SMS — NOT CONNECTED','WhatsApp API — NOT CONNECTED','Regulatory Licensing — NOT CONNECTED','SQLite — ACTIVE'].map((t,i)=>`<div class="flex space"><span class="tiny">${E(t.split(' — ')[0])}</span>${tag(i===4?'Active':'Not connected')}</div>`).join('')}</div><div class="warning" style="margin-top:16px">Do not display active payment collection or official licensing until providers, access credentials and end-to-end tests are completed.</div>`)}</div>`}
function executivePage(s){return `${head(s,btn('Detailed Reports','goto','primary','data-to="62"'))}${hero('Executive Dashboard','Strategic overview of aviation training, student intake, finances and academy operations.','airport','')}<div class="grid cols4" style="margin:18px 0">${metricCard('🎓','students','Registered students')}${metricCard('🛩','verifiedFlightHours','Verified flight hours')}${metricCard('💰','paidRevenue','Verified revenue')}${metricCard('📝','gradePassRate','Pass rate')}</div><div class="grid cols-main">${subSection('Academy performance',`<div id="overview-chart">Loading application history…</div>`)}${subSection('Management destinations',`<div class="help-list">${[49,50,54,56,58,64].map(i=>`<button data-go="${i}">${E(S(i).title)} <span>→</span></button>`).join('')}</div>`)}</div>`}
function communicationsPage(s){return `${head(s,editorButton('messages','＋ Compose Message'))}<div class="grid cols-main">${subSection('Communication log',tableRows(APP.items,'messages'))}${subSection('Communication channels',`<div class="grid cols2">${[['💬','In-app messages'],['✉','Email (not connected)'],['📱','SMS (not connected)'],['🟢','WhatsApp (not connected)']].map(([i,t])=>`<button class="tile" data-action="integration" data-integration="${E(t)}"><span class="emoji">${i}</span><strong>${t}</strong></button>`).join('')}</div><div class="hint" style="margin-top:15px">Messages are saved in the academy database. Sending via external networks requires verified providers.</div>`)}</div>`}
function securityPage(s){return `${head(s)}<div class="grid cols4">${stat('🔒','On','Password hashing')}${stat('📝','On','Audit logging')}${stat('👤','6','Role profiles')}${stat('💾','SQLite','Local database')}</div><div class="grid cols-main" style="margin-top:18px">${subSection('Recent security & activity records',`<div id="audit-list"><div class="hint">Loading audit log…</div></div>`)}${subSection('System administration',`${btn('Download Database Backup','backup','primary full')}<div class="help-list" style="margin-top:15px">${[51,30,60,50].map(i=>`<button data-go="${i}">${E(S(i).title)} <span>→</span></button>`).join('')}</div><div class="warning" style="margin-top:14px">Production launch requires encrypted hosting, HTTPS, a backup/restore test, SSO or MFA, monitoring, rate limits, privacy review and an accredited aviation workflow review.</div>`)}</div>`}
async function recordSave(kind,title,data,id){let result;if(id){result=await api('/record/'+id,'PATCH',{title,data});toast('Changes saved to academy database.')}else{result=await api('/record','POST',{kind,title,data});toast('Record created successfully.')}closeModal();await render();return result}
async function recordView(id){let r=APP.items.find(x=>x.id===id);if(!r){try{r=(await api('/record/'+id)).item}catch(e){return toast(e.message,true)}}if(r.kind==='questions'&&role()==='student')return toast('Question answers are protected; open a quiz to attempt the questions.',true);let fields=Object.entries(r.data||{}).filter(([k])=>!['correct','verificationCode','answers'].includes(k)).map(([k,v])=>`<div class="flex space" style="border-bottom:1px solid #e5ebf4;padding:9px 0;align-items:flex-start"><span class="tiny muted">${E(k.replace(/([A-Z])/g,' $1'))}</span><strong style="font-size:12px;text-align:right;max-width:63%;overflow-wrap:anywhere">${E(Array.isArray(v)?v.join(' | '):String(v).slice(0,450))}</strong></div>`).join('');let doc=['invoices','certificates','payments','flights','grades','tickets','applications','documents'].includes(r.kind)&&APP.user?btn('Download PDF','download','light',`data-id="${r.id}"`):'';let approvals=canApprove(r.kind)&&!['certificates','courses','aircraft','maintenance','lessons'].includes(r.kind)?`<div class="flex" style="margin-top:16px;flex-wrap:wrap">${['Approved','Rejected','Completed'].map(st=>btn(st,'approve',st==='Rejected'?'red':'light',`data-id="${r.id}" data-kind="${E(r.kind)}" data-status="${st}"`)).join('')}${r.kind==='payments'?btn('Mark Paid (verified only)','approve','green',`data-id="${r.id}" data-kind="payments" data-status="Paid"`):''}${r.kind==='tickets'?btn('Mark Present','approve','green',`data-id="${r.id}" data-kind="tickets" data-status="Present"`):''}${r.kind==='flights'?btn('Verify Flight Record','approve','green',`data-id="${r.id}" data-kind="flights" data-status="Verified"`):''}</div>`:'';modal(r.title,`${fields||empty('No details')}<div class="flex" style="flex-wrap:wrap;margin-top:20px">${doc}${canEdit(r.kind)?btn('Edit','edit','primary',`data-id="${r.id}" data-kind="${E(r.kind)}"`):''}${admin()?btn('Delete','delete','red',`data-id="${r.id}"`):''}</div>${approvals}`)}
function parseForm(form){let fd=new FormData(form);let obj={};for(let [k,v] of fd.entries())if(typeof v==='string')obj[k]=v.trim();return obj}
async function submitForm(e){e.preventDefault();let form=e.target,kind=form.dataset.kind||'',id=form.id;let d=parseForm(form);try{
 if(id==='login-form'){let res=await api('/login','POST',d);await refreshMe();toast('Signed in as '+res.user.name);go(['admin','ceo'].includes(role())?50:role()==='instructor'?46:role()==='finance'?54:role()==='admissions'?31:11);return}
 if(id==='register-form'){await api('/register','POST',d);closeModal();toast('Account created. Please sign in.');go(10);return}
 if(id==='forgot-form'){let res=await api('/forgot','POST',d);closeModal();toast(res.message);return}
 if(id==='password-form'){await api('/password','POST',d);form.reset();toast('Password updated.');return}
 if(id==='profile-form'){await api('/profile','POST',d);await refreshMe();closeModal();toast('Profile updated');await render();return}
 if(id==='create-user-form'){let data=await api('/users','POST',d);modal('Account Created',`<div class="success">Account created: <strong>${E(d.name)}</strong></div><div class="field" style="margin-top:15px"><label>Temporary password (displayed once)</label><input class="input" id="temporary-password" readonly value="${E(data.temporaryPassword)}"></div><div class="warning">Copy and share privately. The new user must change this password after signing in.</div>${btn('Copy Password','copyTemp','primary')}`);return}
 if(id==='role-form'){await api('/users/role','POST',{id:form.dataset.id,role:d.role});closeModal();toast('Role changed');await render();return}
 if(id==='seminar-form'){let data={...d,status:'Booked',date:'2026-12-12'};let r=await api('/record','POST',{kind:'tickets',title:'Pilot Training Seminar — '+d.name,data});let saved={id:r.id,code:r.item.data.verificationCode};if(!saved.code)throw Error('Ticket created but no verification code; contact support');localStorage.setItem('irvin_last_ticket',JSON.stringify(saved));toast('Seminar booking confirmed');go(6);return}
 if(id==='application-form'){let data={...d,status:'Submitted'};let r=await api('/record','POST',{kind:'applications',title:d.name+' — '+d.course,data});let code=r.item.data.verificationCode;let content=`<div class="success">Your application has been submitted to IrvinAero admissions.</div><div class="stack" style="margin:17px 0"><p><strong>Application reference:</strong> ${E(r.id.toUpperCase())}</p>${code?`<p><strong>Verification code:</strong> ${E(code)}</p>`:''}<p class="tiny muted">Save this reference. Admissions will review your application and contact you.</p></div><div class="flex">${btn('Track Application','goto','primary','data-to="9"')}${btn('Close','close','white')}</div>`;APP.draft.application={};modal('Application Submitted',content);return}
 if(id==='booking-form'){let data={...d,status:'Pending'};let r=await api('/record','POST',{kind:'bookings',title:'Introductory Flight — '+d.name,data});let saved={id:r.id,code:r.item.data.verificationCode};if(!saved.code)throw Error('Booking saved but verification code missing');localStorage.setItem('irvin_last_booking',JSON.stringify(saved));toast('Booking request submitted. No payment charged.');go(43);return}
 if(id==='lookup-form'){let url='/'+(kind==='applications'?'track':'public-ticket')+'?id='+encodeURIComponent(d.id.trim().toLowerCase())+'&code='+encodeURIComponent(d.code.trim().toUpperCase());let res=await api(url);let r=res.item;if(r.kind==='tickets'){localStorage.setItem('irvin_last_ticket',JSON.stringify({id:r.id,code:d.code}));go(6);return}if(r.kind==='bookings'){localStorage.setItem('irvin_last_booking',JSON.stringify({id:r.id,code:d.code}));go(43);return}let box=$('#lookup-result');if(box)box.innerHTML=`<div class="success" style="margin-top:15px"><strong>Application found:</strong> ${E(r.title)}</div><div class="stack" style="margin-top:13px">${tag(r.data.status)}<p class="tiny">Programme: ${E(r.data.course||'—')}</p><p class="tiny">Submitted: ${fmt(r.created)}</p></div>`;return}
 if(id==='checkin-form'){let res=await api('/public-ticket?id='+encodeURIComponent(d.id.toLowerCase())+'&code='+encodeURIComponent(d.code.toUpperCase()));let record=res.item;if(record.kind!=='tickets')throw Error('Not a seminar ticket');let box=$('#checkin-result');box.innerHTML=`<div class="success" style="margin-top:17px">Ticket verified: <strong>${E(record.data.name)}</strong><br>Current status: ${E(record.data.status||'Booked')}</div><div style="margin-top:12px">${btn(record.data.status==='Present'?'Already Checked In ✓':'Confirm Check-In','approve',record.data.status==='Present'?'light':'green',`data-id="${record.id}" data-kind="tickets" data-status="Present"`)}</div>`;return}
 if(id==='edit-form'){let title=d.title;delete d.title;if(kind==='questions'){d.options=String(d.options||'').split('|').map(x=>x.trim()).filter(Boolean);d.correct=Number(d.correct||0)}await recordSave(kind,title,d,form.dataset.id);return}
 }catch(ex){toast(ex.message,true);console.error(ex)}}
async function setStatus(id,kind,status){if(status==='Paid'&&!confirm('Confirm that you have independently verified this payment? This will mark it Paid.'))return;try{await api('/approval','POST',{id,kind,status});closeModal();toast('Record status changed to '+status);await render()}catch(e){toast(e.message,true)}}
function beginQuiz(isExam){api('/questions').then(r=>{APP.questions=r.items;APP.answers={};if(!r.items.length){toast('No questions available yet',true);return}if(isExam){APP.timerEnd=Date.now()+20*60*1000;if(APP.timer)clearInterval(APP.timer);APP.timer=setInterval(updateClock,1000)}showQuestions(isExam)}).catch(e=>toast(e.message,true))}
function updateClock(){let el=$('#exam-clock');if(!el){if(APP.timer)clearInterval(APP.timer);APP.timer=null;return}let remaining=Math.max(0,Math.ceil((APP.timerEnd-Date.now())/1000));el.textContent=Math.floor(remaining/60).toString().padStart(2,'0')+':'+(remaining%60).toString().padStart(2,'0');if(remaining===0){clearInterval(APP.timer);APP.timer=null;finishQuiz('exam')}}
function showQuestions(isExam){let el=$('#quiz-area');if(!el)return;el.innerHTML=`<form id="quiz-form" data-exam="${isExam?'1':'0'}">${APP.questions.map((r,i)=>`<div style="margin-bottom:22px"><div class="flex space"><strong>Question ${i+1} of ${APP.questions.length}</strong><span class="tiny muted">1 mark</span></div><p style="font-size:14px;font-weight:750">${E(r.title)}</p>${(r.options||[]).map((o,j)=>`<label class="q-option"><input type="radio" name="${E(r.id)}" value="${j}" ${APP.answers[r.id]==j?'checked':''}> ${String.fromCharCode(65+j)}. ${E(o)}</label>`).join('')}</div>`).join('')}<button class="btn primary full" type="submit">Submit ${isExam?'Exam':'Quiz'} for Grading →</button></form>`;}
async function finishQuiz(type){if(!APP.questions.length)return;let f=$('#quiz-form');let fd=f?new FormData(f):new FormData();let answers={};for(let q of APP.questions)answers[q.id]=fd.has(q.id)?Number(fd.get(q.id)):-1;if(APP.timer)clearInterval(APP.timer);APP.timer=null;try{let r=await api('/grade','POST',{type,answers});let result=r.result;let el=$('#quiz-area');el.innerHTML=`<div class="${result.passed?'success':'warning'}" style="text-align:center"><div style="font-size:48px">${result.passed?'🏆':'📘'}</div><h2>${result.percent}%</h2><p>${result.passed?'Assessment passed':'Please revise and retry'} · ${result.score}/${result.total} correct</p></div><div class="flex" style="margin-top:20px">${btn('View Results','goto','primary','data-to="16"')}${btn('Start Again','startQuiz','light',`data-exam="${type==='exam'?'1':'0'}"`)}</div>`;toast('Assessment graded and saved to your records.')}catch(e){toast(e.message,true)}}
function stopCamera(){if(APP.cameraStream){APP.cameraStream.getTracks().forEach(t=>t.stop());APP.cameraStream=null}APP.scanning=false}
async function startScanner(){
 if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){toast('Camera QR scanning is unavailable in this browser. Enter the ticket reference and verification code manually.',true);return}
 let el=$('#qr-video');if(!el)return;
 try{
  let stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});APP.cameraStream=stream;APP.scanning=true;el.style.display='block';el.srcObject=stream;await el.play();let detector=new BarcodeDetector({formats:['qr_code']});
  const scan=async()=>{if(!APP.scanning)return;try{let barcodes=await detector.detect(el);for(let b of barcodes){let m=String(b.rawValue).match(/^IRVINAERO\|tickets\|([a-f0-9]+)\|([A-F0-9]+)$/);if(m){let form=$('#checkin-form');form.querySelector('[name="id"]').value=m[1];form.querySelector('[name="code"]').value=m[2];stopCamera();el.style.display='none';toast('Ticket code scanned');form.requestSubmit();return}}}catch{}if(APP.scanning)requestAnimationFrame(scan)};
  requestAnimationFrame(scan);
 }catch(e){stopCamera();toast('Camera could not start: '+e.message,true)}
}
async function uploadFile(){let inp=$('#doc-upload');if(!inp||!inp.files?.length){toast('Choose a file first',true);return}let f=inp.files[0];if(f.size>3_000_000){toast('File cannot exceed 3 MB',true);return}let base64=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f)});try{let uploaded=await api('/upload','POST',{name:f.name,mime:f.type||'application/octet-stream',base64});await api('/record','POST',{kind:'documents',title:f.name,data:{type:'Supporting Document',fileId:uploaded.id,status:'Pending'}});toast('Document securely uploaded and recorded.');await render()}catch(e){toast(e.message,true)}}
async function extraData(){
 if(APP.screen===51){try{let data=await api('/users'),el=$('#users-list');if(el)el.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Actions</th></tr></thead><tbody>${data.items.map(u=>`<tr><td><strong>${E(u.name)}</strong></td><td>${E(u.email)}</td><td>${tag(u.role)}</td><td>${btn('Manage','manageUser','light sm',`data-id="${u.id}" data-name="${E(u.name)}" data-role="${E(u.role)}"`)}</td></tr>`).join('')}</tbody></table></div>`}catch(e){let el=$('#users-list');if(el)el.innerHTML=`<div class="warning">${E(e.message)}</div>`}}
 if(APP.screen===47){try{let data=await api('/students'),el=$('#students-list');if(el)el.innerHTML=`<div class="stack">${data.items.map(u=>`<div class="feed"><div class="feed-icon">👤</div><div style="flex:1"><strong>${E(u.name)}</strong><p>Student ID: ${E(u.id.toUpperCase())}</p></div>${tag('student')}</div>`).join('')}</div>`}catch(e){let el=$('#students-list');if(el)el.innerHTML=`<div class="warning">${E(e.message)}</div>`}}
 if(APP.screen===64){try{let data=await api('/audit'),el=$('#audit-list');if(el)el.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Actor</th><th>Action</th><th>Entity</th><th>Time</th></tr></thead><tbody>${data.items.slice(0,35).map(x=>`<tr><td>${E(x.actor||'system')}</td><td>${E(x.action)}</td><td>${E(x.entity)}</td><td>${fmt(x.created)}</td></tr>`).join('')}</tbody></table></div>`}catch(e){let el=$('#audit-list');if(el)el.innerHTML=`<div class="warning">${E(e.message)}</div>`}}
 if([49,50,61,62].includes(APP.screen)){
  try{let d=(await api('/overview')).metrics;
   for(let node of $$('[data-metric]')){let key=node.getAttribute('data-metric');let v=d[key];node.textContent=v===null?'Restricted':v===undefined?'—':key.includes('Revenue')||key.includes('Amount')?'US$'+Number(v).toLocaleString():key==='gradePassRate'?v+'%':key==='verifiedFlightHours'?v+' hrs':String(v)}
   let ch=$('#overview-chart');if(ch){let values=Object.entries(d.monthlyApplications||{}).sort().slice(-6);if(!values.length)ch.innerHTML=`<div class="hint">No submitted applications yet. The graph will populate automatically.</div>`;else ch.innerHTML=`<div class="stack">${values.map(([m,v])=>`<div><div class="flex space tiny"><strong>${E(m)}</strong><span>${v} applications</span></div><div class="progress" style="margin-top:5px"><span style="width:${Math.max(5,Math.min(100,v/Math.max(...values.map(p=>p[1]))*100))}%"></span></div></div>`).join('')}</div>`}
  }catch(e){console.warn('Overview not available',e.message)}
 }
}
function attachInputs(){extraData();let filter=$('#record-filter');if(filter)filter.addEventListener('input',e=>{APP.filter=e.target.value;let panel=$('#list-panel');if(panel)panel.innerHTML=tableRows(listFilter(APP.items),S(APP.screen).kind)});let screenSearch=$('#screen-search');if(screenSearch)screenSearch.addEventListener('input',e=>{let t=e.target.value.toLowerCase();$$('.nav-link').forEach(el=>el.style.display=el.textContent.toLowerCase().includes(t)?'flex':'none')})}
document.addEventListener('submit',e=>{if(e.target.id==='quiz-form'){e.preventDefault();finishQuiz(e.target.dataset.exam==='1'?'exam':'quiz');return}submitForm(e)});
document.addEventListener('click',async e=>{let el=e.target.closest('[data-action],[data-go]');if(!el)return;if(el.tagName==='A'||el.tagName==='BUTTON')e.preventDefault();if(el.dataset.go){go(Number(el.dataset.go));return}let action=el.dataset.action,id=el.dataset.id,kind=el.dataset.kind||S(APP.screen).kind;try{switch(action){
 case'goto':go(Number(el.dataset.to));break;
 case'drawer':APP.drawer=!APP.drawer;$$('.side,.scrim').forEach(x=>x.classList.toggle('open',APP.drawer));break;
 case'close':closeModal();break;
 case'logout':await api('/logout','POST',{});await refreshMe();toast('Signed out');go(1);break;
 case'reload':render();break;
 case'new':if(!APP.user&&kind!=='tickets'&&kind!=='bookings'&&kind!=='applications'){toast('Log in first',true);go(10);return}openEditor(kind);break;
 case'edit':closeModal();openEditor(kind,id);break;
 case'delete':if(!confirm('Permanently delete this record?'))return;await api('/record/'+id,'DELETE');toast('Record deleted');closeModal();await render();break;
 case'details':await recordView(id);break;
 case'approve':await setStatus(id,kind,el.dataset.status);break;
 case'chooseCourse':APP.course=el.dataset.course;go(3);break;
 case'tab':APP.tab=el.dataset.tab;await render();break;
 case'createUser':modal('Create Academy Account',`<form id="create-user-form"><div class="field"><label>Full name</label><input class="input" name="name" required></div><div class="field"><label>Email address</label><input class="input" name="email" type="email" required></div><div class="field"><label>Account role</label><select class="select" name="role">${['student','instructor','admissions','finance','admin','ceo'].map(r=>`<option value="${r}">${r}</option>`).join('')}</select></div><button type="submit" class="btn primary full">Create Account</button></form>`);break;
 case'copyTemp':{let field=$('#temporary-password');if(field){field.select();try{await navigator.clipboard.writeText(field.value);toast('Password copied')}catch{toast('Select and copy the displayed password manually')}}break}
 case'manageUser':{let username=el.dataset.name,rr=el.dataset.role;modal('Manage '+username,`<form id="role-form" data-id="${E(id)}"><div class="field"><label>Access role</label><select class="select" name="role">${['student','instructor','admissions','finance','admin','ceo'].map(x=>`<option value="${x}" ${x===rr?'selected':''}>${x}</option>`).join('')}</select></div><button class="btn primary" type="submit">Save Role</button> ${btn('Reset Password','resetUser','red',`data-id="${E(id)}"`)}</form>`);break}
 case'resetUser':{if(!confirm('Issue a new temporary password and invalidate existing sessions for this user?'))return;let response=await api('/users/reset','POST',{id});modal('Temporary Password Issued',`<div class="warning">Share the one-time temporary password privately. Previous sessions have been invalidated.</div><div class="field" style="margin-top:14px"><label>Temporary password</label><input class="input" id="temporary-password" readonly value="${E(response.temporaryPassword)}"></div>${btn('Copy Password','copyTemp','primary')}`);break}
 case'editProfile':modal('Edit Your Profile',`<form id="profile-form"><div class="field"><label>Full name</label><input class="input" name="name" value="${E(APP.user?.name||'')}" required></div><div class="field"><label>Email</label><input class="input" type="email" name="email" value="${E(APP.user?.email||'')}" required></div><button class="btn primary full" type="submit">Save Profile</button></form>`);break;
 case'collection':{let kind=el.dataset.kind;let rows=await getRecords(kind);modal('Manage '+kind,`${canEdit(kind)?btn('＋ New '+kind.slice(0,-1),'new','primary',`data-kind="${E(kind)}"`):''}<div style="margin-top:12px">${tableRows(rows,kind)}</div>`);break}
 case'scanQR':await startScanner();break;
 case'backup':window.open('/api/backup','_blank','noopener');toast('Database backup download requested.');break;
 case'register':modal('Create Student Account',`<form id="register-form"><div class="field"><label>Full name</label><input class="input" name="name" required></div><div class="field"><label>Email address</label><input class="input" name="email" type="email" required></div><div class="field"><label>Password (at least 10 characters)</label><input class="input" name="password" type="password" minlength="10" required></div><button class="btn primary full" type="submit">Create Account →</button></form>`);break;
 case'forgot':modal('Recover Your Account',`<div class="warning" style="margin-bottom:16px">Email and SMS delivery are not yet connected. For production recovery, contact academy administration until secure reset delivery is configured.</div><form id="forgot-form"><div class="field"><label>Registered email</label><input class="input" name="email" type="email" required></div><button class="btn primary full" type="submit">Request Recovery Help</button></form>`);break;
 case'demoLogin':{let r=el.dataset.role;let res=await api('/login','POST',{email:r+'@irvinaero.demo',password:'Demo2026!'});await refreshMe();toast('Signed in as '+r);go(['admin','ceo'].includes(r)?50:r==='instructor'?46:r==='finance'?54:r==='admissions'?31:11);break}
 case'lessonPlay':{let x=APP.items.find(a=>a.id===APP.selected)||APP.items[0];if(x)modal('Lesson: '+x.title,`<p class="sub">${E(x.data.content)}</p><div class="warning" style="margin:18px 0">No hosted video asset is attached to this lesson. An authorised instructor can add learning resources and approved recordings.</div>${btn('Save Note','lessonNote','primary',`data-id="${x.id}"`)}`);break}
 case'lessonNote':modal('Save a Lesson Note',`<form id="edit-form" data-kind="notes" data-id=""><div class="field"><label>Note title</label><input name="title" class="input" required value="Personal study note"></div>${formFields('notes',{lesson:APP.items.find(x=>x.id===id)?.title||'',course:APP.course,completed:'No'})}<button type="submit" class="btn primary full">Save Note</button></form>`);break;
 case'lessonComplete':await api('/record','POST',{kind:'notes',title:'Completed: '+(APP.items.find(x=>x.id===id)?.title||'Lesson'),data:{lesson:id,completed:'Yes',course:APP.course}});toast('Lesson completion saved');break;
 case'selectLesson':APP.selected=id;await render();break;
 case'nextLesson':{let i=APP.items.findIndex(x=>x.id===id);APP.selected=APP.items[(i+1)%APP.items.length]?.id;await render();break}
 case'submitAssignment':{let options=APP.items.map(x=>`<option value="${E(x.title)}">${E(x.title)}</option>`).join('');if(!options)return toast('No assignments available',true);modal('Submit an Assignment',`<form id="edit-form" data-kind="submissions" data-id=""><div class="field"><label>Submission title</label><input class="input" name="title" required value="My Assignment Submission"></div><div class="field"><label>Assignment</label><select class="select" name="assignment">${options}</select></div><div class="field"><label>Answer / document link</label><textarea class="textarea" name="answer" required></textarea></div><input type="hidden" name="status" value="Submitted"><button class="btn primary full" type="submit">Send to Instructor</button></form>`);break}
 case'startQuiz':beginQuiz(el.dataset.exam==='1');break;
 case'joinClass':{let x=APP.items.find(x=>x.id===id);let u=x?.data.location||'';if(/^https:\/\//i.test(u)){if(confirm('Open the class link on an external site?'))window.open(u,'_blank','noopener,noreferrer')}else modal('Class details',`<p><strong>${E(x?.title||'')}</strong></p><p class="tiny muted">${E(u||'No live-class URL provided.')}</p><div class="warning">The instructor has not configured an online class link. See the teaching schedule or contact your instructor.</div>${btn('Contact Support','goto','light','data-to="26"')}`);break}
 case'calendarDay':{let d=Number(el.dataset.day);let x=APP.items.filter(x=>Number(String(x.data.start||'').slice(8,10))===d);modal('Events — December '+d, x.length?cardList(x,'classes'):empty('No classes on this date'));break}
 case'upload':await uploadFile();break;
 case'print':window.print();break;
 case'download':window.open('/api/document/'+id,'_blank','noopener');break;
 case'faq':{let qs=['Admissions applications are submitted from Screen 8. Save the reference to track approval.','Open Assignments on Screen 13, select the relevant assignment and submit your answer.','Payments are not automatically collected. Submit a verified transaction reference, then finance staff approve the record.','After seminar booking on Screen 5, the system provides a QR ticket and reference on Screen 6.'];modal('Support answer',`<p class="sub">${E(qs[Number(el.dataset.faq)]||'Contact support for assistance.')}</p>${btn('Open Support Ticket','goto','primary','data-to="26"')}`);break}
 case'settingInfo':modal('Account Preferences',`<p class="sub">Security and communication settings are controlled by the academy. You can change your account password on Screen 30, or ask support for further changes.</p>${btn('Contact Support','goto','primary','data-to="26"')}`);break;
 case'integration':modal(el.dataset.integration,`<div class="warning">This integration is not configured in the staging platform. It must be connected, authorised and tested with the service provider before use.</div><p class="tiny muted">In the meantime, relevant local forms, logs and manual workflows remain available for testing.</p>${btn('Return','close','light')}`);break;
 case'report':modal(el.dataset.report,`<p class="sub">${E(el.dataset.report)} is available as a printable draft. The financial and academic totals must be calculated from confirmed academy records before official use.</p>${btn('Print / Save as PDF','print','primary')}`);break;
 default:toast('This control has no handler yet: '+action,true)
 }}catch(err){console.error(err);toast(err.message,true)}});
window.addEventListener('hashchange',()=>{let m=location.hash.match(/#\/screen\/(\d+)/);let n=m?Number(m[1]):1;if(n!==APP.screen)go(n)});
window.addEventListener('unhandledrejection',e=>{console.error('Uncaught app error',e.reason);toast('Something went wrong: '+String(e.reason?.message||e.reason),true)});
async function start(){try{await refreshMe();let m=location.hash.match(/#\/screen\/(\d+)/);APP.screen=m?Number(m[1]):1;await render()}catch(e){console.error(e);$('#app').innerHTML=`<div style="max-width:600px;margin:80px auto;padding:30px;background:white;border-radius:12px"><h2>Could not connect to the server</h2><p>${E(e.message)}</p><p>Start the Python server to use the app. Data is not accessible by opening index.html directly.</p></div>`}}
start();